-- Legal Metrology Stage 11: snapshot-backed report artifacts and versioning.
create sequence if not exists public.report_number_seq;
create or replace function public.next_report_number() returns text language sql security definer set search_path = public as $$ select 'RPT-' || extract(year from timezone('utc', now()))::text || '-' || lpad(nextval('public.report_number_seq')::text, 6, '0') $$;
create table if not exists public.reports (id uuid primary key default gen_random_uuid(), report_number text not null unique, report_type text not null, inspection_id uuid references public.inspections(id) on delete restrict, violation_id uuid references public.violations(id) on delete restrict, sample_id uuid references public.samples(id) on delete restrict, laboratory_report_id uuid references public.lab_reports(id) on delete restrict, title text not null, description text, status text not null default 'Draft' check (status in ('Draft', 'Generated', 'Pending Review', 'Reviewed', 'Approved', 'Published', 'Superseded', 'Cancelled')), generated_by uuid references public.profiles(id) on delete set null, generated_at timestamptz, reviewed_by uuid references public.profiles(id) on delete set null, reviewed_at timestamptz, approved_by uuid references public.profiles(id) on delete set null, approved_at timestamptz, version integer not null default 1, file_path text, editable_file_path text, checksum text, signature_status text, signed_by uuid references public.profiles(id) on delete set null, signed_at timestamptz, signature_reference text, created_at timestamptz not null default timezone('utc', now()), updated_at timestamptz not null default timezone('utc', now()));
create table if not exists public.report_versions (id uuid primary key default gen_random_uuid(), report_id uuid not null references public.reports(id) on delete restrict, version_number integer not null, file_path text, editable_file_path text, generated_by uuid references public.profiles(id) on delete set null, generated_at timestamptz, checksum text, change_summary text, status text not null, created_at timestamptz not null default timezone('utc', now()), unique (report_id, version_number));
create table if not exists public.report_data_snapshots (id uuid primary key default gen_random_uuid(), report_id uuid not null references public.reports(id) on delete restrict, snapshot_json jsonb not null, created_at timestamptz not null default timezone('utc', now()));
create or replace function public.is_report_manager() returns boolean language sql stable security definer set search_path = public as $$ select exists (select 1 from public.profiles where auth_user_id = auth.uid() and status = 'active' and user_type = 'government' and role in ('super_admin', 'controller', 'assistant_controller', 'inspector', 'clerk')) $$;
create or replace function public.report_scope(target_report_id uuid) returns boolean language sql stable security definer set search_path = public as $$ select exists (select 1 from public.reports r left join public.inspections i on i.id = r.inspection_id where r.id = target_report_id and ((public.is_report_manager() and (i.id is null or public.inspection_scope(i.office_id, i.business_id, i.inspector_id))) or exists (select 1 from public.profiles p where p.auth_user_id = auth.uid() and p.user_type = 'business' and p.business_id = i.business_id))) $$;
alter table public.reports enable row level security; alter table public.report_versions enable row level security; alter table public.report_data_snapshots enable row level security;
create policy reports_read_scoped on public.reports for select to authenticated using (report_scope(id));
create policy reports_manager_insert on public.reports for insert to authenticated with check (public.is_report_manager() and (inspection_id is null or exists (select 1 from public.inspections i where i.id = inspection_id and public.inspection_scope(i.office_id, i.business_id, i.inspector_id))));
create policy reports_manager_update on public.reports for update to authenticated using (public.is_report_manager() and report_scope(id)) with check (public.is_report_manager());
create policy report_versions_read_scoped on public.report_versions for select to authenticated using (report_scope(report_id));
create policy report_versions_manager_write on public.report_versions for insert to authenticated with check (public.is_report_manager() and report_scope(report_id));
create policy snapshots_read_scoped on public.report_data_snapshots for select to authenticated using (report_scope(report_id));
create policy snapshots_manager_write on public.report_data_snapshots for insert to authenticated with check (public.is_report_manager() and report_scope(report_id));
insert into storage.buckets (id, name, public) values ('reports', 'reports', false) on conflict (id) do nothing;
create policy reports_storage_read on storage.objects for select to authenticated using (bucket_id = 'reports');
create policy reports_storage_write on storage.objects for insert to authenticated with check (bucket_id = 'reports' and public.is_report_manager());
create index if not exists reports_inspection_idx on public.reports(inspection_id); create index if not exists reports_violation_idx on public.reports(violation_id); create index if not exists reports_sample_idx on public.reports(sample_id); create index if not exists reports_status_idx on public.reports(status); create index if not exists reports_type_idx on public.reports(report_type); create index if not exists report_versions_report_idx on public.report_versions(report_id); create index if not exists report_snapshots_report_idx on public.report_data_snapshots(report_id);